using System;
using UnityEngine;
using UnityEditor;
public static class ValidateSerpentineDrive
{
 public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play");var route=UnityEngine.Object.FindAnyObjectByType<LongRouteStream>();var car=route.truck.GetComponent<ForestKamazController>();var rb=car.GetComponent<Rigidbody>();var pos=rb.position;var rot=rb.rotation;var mode=Physics.simulationMode;bool paused=EditorApplication.isPaused;double progress=0;
 try{Physics.simulationMode=SimulationMode.Script;EditorApplication.isPaused=true;route.EnsureWindow(0,true);rb.position=route.Point(0)+Vector3.up*.5f;rb.rotation=Quaternion.LookRotation(route.Tangent(0));car.transform.SetPositionAndRotation(rb.position,rb.rotation);rb.linearVelocity=Vector3.zero;rb.angularVelocity=Vector3.zero;car.testControl=true;car.lowRange=true;Physics.SyncTransforms();car.testBrake=true;car.SendMessage("Update");var chains=car.GetComponent<TruckChains>();chains.RequestToggle();chains.Advance(5);
 for(int i=0;i<35000;i++){float best=float.MaxValue;double nearest=progress;for(double s=Math.Max(0,progress-5);s<=progress+12;s+=1){float d=(route.Point(s)-rb.position).sqrMagnitude;if(d<best){best=d;nearest=s;}}progress=nearest;if(i%100==0)route.EnsureWindow((int)(progress/route.chunkMetres),true);var target=car.transform.InverseTransformPoint(route.Point(progress+8));car.testSteer=Mathf.Clamp(Mathf.Atan2(target.x,Mathf.Max(1,target.z))*Mathf.Rad2Deg/24,-1,1);car.testBrake=false;car.testThrottle=car.SpeedKmh<16?.8f:0;car.SendMessage("Update");car.SendMessage("FixedUpdate");Physics.Simulate(.02f);car.SendMessage("LateUpdate");if(rb.position.y<route.Point(progress).y-2)throw new Exception("Below entrance road");if(progress>1400)return "PASS actual KAMAZ drove from original forest entrance through first 1400m, including join and first chunk seam";}
 string detail="";foreach(var wheel in car.wheels){if(wheel.GetGroundHit(out var hit))detail+=" | "+hit.collider.name+" p="+hit.point+" torque="+wheel.motorTorque+" brake="+wheel.brakeTorque;}foreach(var other in Physics.OverlapBox(rb.position+car.transform.forward, new Vector3(2,1.5f,4),car.transform.rotation,~0,QueryTriggerInteraction.Ignore)){if(other.attachedRigidbody==rb)continue;foreach(var own in car.GetComponents<Collider>()){if(Physics.ComputePenetration(own,own.transform.position,own.transform.rotation,other,other.transform.position,other.transform.rotation,out var direction,out var distance))detail+=" penetration "+other.name+" "+distance+" dir="+direction;}}throw new Exception("Entrance obstructed at "+progress+"m speed="+car.SpeedKmh+" position="+rb.position+detail);
 }finally{car.testControl=false;car.testThrottle=0;car.testBrake=false;car.testSteer=0;car.lowRange=false;rb.position=pos;rb.rotation=rot;car.transform.SetPositionAndRotation(pos,rot);rb.linearVelocity=Vector3.zero;rb.angularVelocity=Vector3.zero;Physics.simulationMode=mode;EditorApplication.isPaused=paused;}
 }
}


